        X[n], Y[n], Wd[n], Ht[n] = tonumber(x), tonumber(y), tonumber(w), tonumber(h)
    end
    levels[li] = { step = L.step, X = X, Y = Y, W = Wd, H = Ht, n = n }
end

local C_name, C_lon, C_lat, C_pop, CN = {}, {}, {}, {}, 0
for name, lon, lat, pop in CITY_DATA:gmatch("([^;|]+)|([%-%d%.]+)|([%-%d%.]+)|(%d+)") do
    CN = CN + 1
    C_name[CN], C_lon[CN], C_lat[CN], C_pop[CN] = name, tonumber(lon), tonumber(lat), tonumber(pop)
end

-- Objects (creation order = paint order) -----------------------------------
local HIDE_Y = -1000

local function new_rect(color)
    local o = drawer.rectangle(0, HIDE_Y, 0, 0)
    o.set_color(color)
    return { o = o, x = 0, y = HIDE_Y, w = 0, h = 0 }
end

local function place(e, x, y, w, h)
    if e.x ~= x or e.y ~= y then e.o.set_position(x, y); e.x, e.y = x, y end
    if e.w ~= w or e.h ~= h then e.o.set_size(w, h); e.w, e.h = w, h end
end

local function hide(e)
    if e.y ~= HIDE_Y then e.o.set_position(0, HIDE_Y); e.x, e.y = 0, HIDE_Y end
end

local ocean = new_rect("#0e2a4a")

local land = {}
for i = 1, LAND_POOL do land[i] = new_rect("#3a9d5d") end
local land_used = 0

local vlines, hlines = {}, {}
for i = 1, 40 do vlines[i] = new_rect("#1d4570") end
for i = 1, 30 do hlines[i] = new_rect("#1d4570") end
local vused, hused = 0, 0

local dots = {}
for i = 1, CITY_POOL do dots[i] = new_rect("#f43f5e") end
local dots_used = 0

local labels = {}
for i = 1, CITY_POOL do
    local t = drawer.text(0, HIDE_Y, "", 14, "Calibri", "Regular", "#ffffff", "left")
    t.set_outline("#000000", 2)
    labels[i] = { o = t, x = 0, y = HIDE_Y, s = "", al = "left", size = 14 }
end

local title = drawer.text(0, 0, "Карта мира", 30, "Calibri", "Bold", "#ffffff", "left")
local readout = drawer.text(0, 0, "", 20, "Calibri", "Regular", "#cbd5e1", "center")
local hint = drawer.text(0, 0, "Колесо — масштаб, перетаскивание — сдвиг", 16, "Calibri", "Regular", "#64748b", "right")

local function make_button(text, fn)
    local b = drawer.button(0, 0, text)
    b.set_color("#3b82f6")
    b.set_text_color("#ffffff")
    b.event("on_selected", function() b.set_color("#60a5fa") end)
    b.event("on_deselected", function() b.set_color("#3b82f6") end)
    b.event("on_left_click", fn)
    return b
end

-- View ---------------------------------------------------------------------
local W, H = 0, 0
local MX, MY, MW, MH = 0, 0, 100, 100   -- map area on screen
local S = 1                             -- ui scale
local view = { clon = 0, clat = LAT_TOP - LAT_EXT / 2, z = 1 }
local zmin = 1
local dirty = true

local function clamp(v, a, b)
    if v < a then return a end
    if v > b then return b end
    return v
end

local function clamp_view()
    view.z = clamp(view.z, zmin, ZMAX)
    local hw, hh = (MW / 2) / view.z, (MH / 2) / view.z
    if hw * 2 >= 360 then view.clon = 0 else view.clon = clamp(view.clon, -180 + hw, 180 - hw) end
    if hh * 2 >= LAT_EXT then view.clat = LAT_TOP - LAT_EXT / 2
    else view.clat = clamp(view.clat, LAT_TOP - LAT_EXT + hh, LAT_TOP - hh) end
end

local function fx(lon) return MX + MW / 2 + (lon - view.clon) * view.z end
local function fy(lat) return MY + MH / 2 + (view.clat - lat) * view.z end

local function round(v) return math.floor(v + 0.5) end

-- zoom keeping the geographic point under screen position (sx, sy) fixed
local function zoom_at(factor, sx, sy)
    local lon = view.clon + (sx - (MX + MW / 2)) / view.z
    local lat = view.clat - (sy - (MY + MH / 2)) / view.z
    view.z = clamp(view.z * factor, zmin, ZMAX)
    view.clon = lon - (sx - (MX + MW / 2)) / view.z
    view.clat = lat + (sy - (MY + MH / 2)) / view.z
    clamp_view()
    dirty = true
end

local btn_plus = make_button("+", function() zoom_at(1.6, MX + MW / 2, MY + MH / 2) end)
local btn_minus = make_button("-", function() zoom_at(1 / 1.6, MX + MW / 2, MY + MH / 2) end)
local btn_reset = make_button("Весь мир", function()
    view.z, view.clon, view.clat = zmin, 0, LAT_TOP - LAT_EXT / 2
    clamp_view()
    dirty = true
end)

-- Drawing ------------------------------------------------------------------
local LINE_STEPS = { 30, 15, 10, 5, 2, 1, 0.5, 0.2 }

local shown = { x = {}, y = {}, i = {} }
local shown_n = 0

local function redraw()
    local z = view.z
    local mr, mb = MX + MW, MY + MH

    -- ocean (only the part of the world that is inside the view)
    do
        local x0, x1 = math.max(MX, round(fx(-180))), math.min(mr, round(fx(180)))
        local y0, y1 = math.max(MY, round(fy(LAT_TOP))), math.min(mb, round(fy(LAT_TOP - LAT_EXT)))
        if x1 > x0 and y1 > y0 then place(ocean, x0, y0, x1 - x0, y1 - y0) else hide(ocean) end
    end

    -- land
    local lv = z < 5 and levels[1] or (z < 14 and levels[2] or levels[3])
    local step = lv.step
    local X, Y, Wd, Ht = lv.X, lv.Y, lv.W, lv.H
    local used = 0
    local left_lon = -180 + (MX - (MX + MW / 2)) / z + view.clon
    for i = 1, lv.n do
        local x0 = round(fx(-180 + X[i] * step))
        local x1 = round(fx(-180 + (X[i] + Wd[i]) * step))
        if x1 > MX and x0 < mr then
            local y0 = round(fy(LAT_TOP - Y[i] * step))
            local y1 = round(fy(LAT_TOP - (Y[i] + Ht[i]) * step))
            if y1 > MY and y0 < mb then
                if x0 < MX then x0 = MX end
                if x1 > mr then x1 = mr end
                if y0 < MY then y0 = MY end
                if y1 > mb then y1 = mb end
                if used < LAND_POOL then
                    used = used + 1
                    place(land[used], x0, y0, math.max(1, x1 - x0), math.max(1, y1 - y0))
                end
            end
        end
    end
    for i = used + 1, land_used do hide(land[i]) end
    land_used = used

    -- graticule
    local gstep = LINE_STEPS[#LINE_STEPS]
    for _, s in ipairs(LINE_STEPS) do
        if s * z >= 70 then gstep = s; break end
    end
    local lw = math.max(1, round(S))
    local lon_min = view.clon - (MW / 2) / z
    local lon_max = view.clon + (MW / 2) / z
    local lat_max = view.clat + (MH / 2) / z
    local lat_min = view.clat - (MH / 2) / z
    local n = 0
    local lon = math.ceil(math.max(lon_min, -180) / gstep) * gstep
    while lon <= math.min(lon_max, 180) and n < #vlines do
        n = n + 1
        local x = round(fx(lon))
        local e = vlines[n]
        place(e, x, math.max(MY, round(fy(LAT_TOP))), lw, math.min(mb, round(fy(LAT_TOP - LAT_EXT))) - math.max(MY, round(fy(LAT_TOP))))
        lon = lon + gstep
    end
    for i = n + 1, vused do hide(vlines[i]) end
    vused = n
    n = 0
    local lat = math.ceil(math.max(lat_min, LAT_TOP - LAT_EXT) / gstep) * gstep
    while lat <= math.min(lat_max, LAT_TOP) and n < #hlines do
        n = n + 1
        local y = round(fy(lat))
        local x0, x1 = math.max(MX, round(fx(-180))), math.min(mr, round(fx(180)))
        place(hlines[n], x0, y, x1 - x0, lw)
        lat = lat + gstep
    end
    for i = n + 1, hused do hide(hlines[i]) end
    hused = n

    -- cities (largest first; amount grows with zoom)
    local cap = math.min(CITY_POOL, math.floor(20 + z * 7))
    local d = math.max(4, round(6 * S))
    local cell_w, cell_h = 110 * S, 16 * S
    local occupied = {}
    local count, lcount = 0, 0
    shown_n = 0
    local fsize = math.max(10, round(14 * S))
    for i = 1, CN do
        if count >= cap then break end
        local x, y = fx(C_lon[i]), fy(C_lat[i])
        if x > MX + 2 and x < mr - 2 and y > MY + 2 and y < mb - 2 then
            count = count + 1
            local px, py = round(x) - d // 2, round(y) - d // 2
            place(dots[count], px, py, d, d)
            shown_n = shown_n + 1
            shown.x[shown_n], shown.y[shown_n], shown.i[shown_n] = x, y, i

            local key = math.floor(x / cell_w) * 100000 + math.floor(y / cell_h)
            if not occupied[key] and not occupied[key + 1] and not occupied[key - 1] then
                occupied[key] = true
                lcount = lcount + 1
                local lb = labels[lcount]
                local name = C_name[i]
                local label_w = (utf8.len(name) or #name) * 7.5 * (fsize / 14)
                local al, lx = "left", x + d
                if lx + label_w > mr then al, lx = "right", x - d end
                lx, py = round(lx), round(y - fsize * 0.65)
                if lb.size ~= fsize then lb.o.set_font_style("Calibri", "Regular", fsize); lb.size = fsize end
                if lb.al ~= al then lb.o.set_align(al); lb.al = al end
                if lb.s ~= name then lb.o.set_text(name); lb.s = name end
                if lb.x ~= lx or lb.y ~= py then lb.o.set_position(lx, py); lb.x, lb.y = lx, py end
            end
        end
    end
    for i = count + 1, dots_used do hide(dots[i]) end
    dots_used = count
    for i = lcount + 1, CITY_POOL do
        local lb = labels[i]
        if lb.y ~= HIDE_Y then lb.o.set_position(0, HIDE_Y); lb.x, lb.y = 0, HIDE_Y end
    end
end

-- Layout -------------------------------------------------------------------
local function layout(w, h)
    local was_fit = (view.z <= zmin * 1.0001)
    W, H = w, h
    S = clamp(math.min(w / 1280, h / 700), 0.6, 2)
    local top, bottom = 56 * S, 44 * S
    MX, MY = round(w * 0.02), round(top)
    MW, MH = round(w * 0.96), round(h - top - bottom)
    zmin = math.min(MW / 360, MH / LAT_EXT)
    if was_fit then view.z = zmin end

    title.set_font_style("Calibri", "Bold", 30 * S)
    title.set_position(MX, 10 * S)
    hint.set_font_style("Calibri", "Regular", 16 * S)
    hint.set_position(MX + MW, MY + MH + 12 * S)
    readout.set_font_style("Calibri", "Regular", 20 * S)
    readout.set_position(w / 2, MY + MH + 10 * S)

    local bw, bh, gap = 44 * S, 38 * S, 8 * S
    local by = 9 * S
    local rx = MX + MW
    btn_reset.set_size(120 * S, bh); btn_reset.set_font_style("Calibri", "Regular", 18 * S)
    btn_reset.set_position(rx - 120 * S, by)
    rx = rx - 120 * S - gap
    btn_minus.set_size(bw, bh); btn_minus.set_font_style("Calibri", "Bold", 22 * S)
    btn_minus.set_position(rx - bw, by)
    rx = rx - bw - gap
    btn_plus.set_size(bw, bh); btn_plus.set_font_style("Calibri", "Bold", 22 * S)
    btn_plus.set_position(rx - bw, by)

    clamp_view()
    dirty = true
end

local function fmt_coord(v, pos, neg)
    return string.format("%.2f° %s", math.abs(v), v >= 0 and pos or neg)
end

local function fmt_pop(k)
    if k >= 1000 then return string.format("%.1f млн", k / 1000) end
    return k .. " тыс."
end

-- Main loop ----------------------------------------------------------------
local w0, h0 = drawer.get_size_screen()
view.z = 0
layout(w0, h0)
view.z = zmin
clamp_view()

local dragging, lx, ly = false, 0, 0
local last_text = ""

while true do
    local w, h = drawer.get_size_screen()
    if w ~= W or h ~= H then layout(w, h) end

    local mx, my, down, inside = drawer.get_mouse()
    local in_map = inside and mx >= MX and mx <= MX + MW and my >= MY and my <= MY + MH

    -- zoom with the wheel
    local wheel = drawer.get_wheel()
    if wheel ~= 0 and in_map then zoom_at(1.25 ^ wheel, mx, my) end

    -- drag to pan
    if down then
        if dragging then
            view.clon = view.clon - (mx - lx) / view.z
            view.clat = view.clat + (my - ly) / view.z
            clamp_view()
            if mx ~= lx or my ~= ly then dirty = true end
        elseif in_map then
            dragging = true
        end
        lx, ly = mx, my
    else
        dragging = false
    end

    if dirty then
        dirty = false
        redraw()
    end

    -- readout
    local text = ""
    if in_map then
        local lon = view.clon + (mx - (MX + MW / 2)) / view.z
        local lat = view.clat - (my - (MY + MH / 2)) / view.z
        if lon >= -180 and lon <= 180 and lat <= LAT_TOP and lat >= LAT_TOP - LAT_EXT then
            text = fmt_coord(lat, "с.ш.", "ю.ш.") .. ",  " .. fmt_coord(lon, "в.д.", "з.д.")
            local best, bd = nil, (12 * S) ^ 2
            for k = 1, shown_n do
                local dd = (shown.x[k] - mx) ^ 2 + (shown.y[k] - my) ^ 2
                if dd < bd then best, bd = shown.i[k], dd end
            end
            if best then
                text = C_name[best] .. " (" .. fmt_pop(C_pop[best]) .. ")   |   " .. text
            end
        end
    end
    if text ~= last_text then
        readout.set_text(text)
        last_text = text
    end

    sleep(0.016)
end
